-- Úvod webu: místo AI obrázku skutečná fotka ze studia (přání studia 26. 11. 2026) – plyšová chobotnička, maskot OCTOPUSH,
-- s barevnými kettlebelly na podlaze sálu. Je to skutečná fotka, proto bez označení AI.
-- Nastaví se jen při prvním spuštění (dokud fotka není mezi nahranými); fotku, kterou studio později vybere v Obsah webu
-- → Úvod – hlavní část, opakované spuštění nepřepíše. Dosavadní obrázek zůstává mezi nahranými.

-- 1) Fotka a její popis pro nevidomé na úvodní stránce.
INSERT INTO "content" ("key", "value", "updated_at")
SELECT k, v, now() FROM (VALUES
  ('homeHero.image', '/media/3f584c4d-c98b-4163-9dd8-1cfd93246a5e.webp'),
  ('homeHero.imageAlt', 'Plyšová chobotnička OCTOPUSH s barevnými kettlebelly na podlaze studia')
) AS x(k, v)
WHERE NOT EXISTS (SELECT 1 FROM "media" WHERE "id" = '3f584c4d-c98b-4163-9dd8-1cfd93246a5e')
ON CONFLICT ("key") DO UPDATE SET "value" = EXCLUDED."value", "updated_at" = now();
--> statement-breakpoint
-- 2) Samotná fotka, uložená jako nahraná (ukáže se hned).
INSERT INTO "media" ("id", "filename", "mime", "width", "height", "size", "data") VALUES
  ('3f584c4d-c98b-4163-9dd8-1cfd93246a5e', 'uvod-chobotnicka.webp', 'image/webp', 1200, 1666, 122232, decode('', 'base64'))
ON CONFLICT ("id") DO NOTHING;
